(()=>{
const $=id=>document.getElementById(id),config=window.WELCOME_FIREBASE_CONFIG,demo=!config?.projectId;let schema=[],values={},firebase=null,user=null,dirty=false,ready=false,busy=false;const names={header:'Шапка сайта',about:'О школе',courses:'Программы',life:'Жизнь школы',reviews:'Отзывы',details:'Занятия и цены',faq:'Вопросы и ответы',contact:'Контакты'};const status=t=>$('status').textContent=t;
function authError(error){const code=error?.code||'unknown';console.warn('Welcome sign-in:',code);const messages={'auth/invalid-credential':'Почта или пароль не совпадают. Введите пароль, который вы задали по ссылке из письма.','auth/wrong-password':'Пароль не совпадает. Можно задать новый кнопкой «Получить / восстановить пароль».','auth/user-not-found':'Не удалось войти с этой почтой и паролем. Проверьте почту или восстановите пароль.','auth/invalid-email':'Проверьте адрес электронной почты.','auth/too-many-requests':'Слишком много попыток входа. Подождите несколько минут и попробуйте снова.','auth/network-request-failed':'Нет соединения с сервисом входа Firebase. Проверьте интернет и попробуйте ещё раз.','auth/user-disabled':'Доступ к этой учётной записи отключён.','auth/operation-not-allowed':'Вход по паролю отключён в настройках проекта.','auth/web-storage-unsupported':'Браузер блокирует хранение сессии. Откройте админку в обычной вкладке браузера.'};return (messages[code]||'Не удалось войти. Сообщите разработчику код ошибки: '+code);}

const preview=()=>$('site-preview').contentWindow.postMessage({type:'welcome-preview',fields:values},location.origin);
function render(){const section=$('section').value,query=$('search').value.toLowerCase();$('fields').replaceChildren();schema.filter(f=>(section==='all'||f.section===section)&&[f.ru,f.en,values[f.id]?.ru,values[f.id]?.en].some(t=>(t||'').toLowerCase().includes(query))).forEach(f=>{const box=document.createElement('article');box.className='field';const info=document.createElement('small');info.textContent=names[f.section]||f.section;box.append(info);const grid=document.createElement('div');grid.className='columns';['ru','en'].forEach(lang=>{const label=document.createElement('label'),span=document.createElement('span'),input=document.createElement('textarea');span.textContent=lang==='ru'?'Русский':'English';input.value=values[f.id]?.[lang]??f[lang];input.maxLength=12000;input.lang=lang;input.addEventListener('input',()=>{values[f.id]={...(values[f.id]||{ru:f.ru,en:f.en}),[lang]:input.value};dirty=true;status('Есть несохранённые изменения');if(!$('site-preview').hidden)preview()});label.append(span,input);grid.append(label)});box.append(grid);$('fields').append(box)})}
async function load(){if(!schema.length||ready)return;if(!demo&&!user)return;try{if(demo){const saved=localStorage.getItem('welcome-demo-draft');values=saved?JSON.parse(saved):{}}else{const snap=await firebase.getDoc(firebase.doc(firebase.db,'siteContent','draft'));if(snap.exists())values=snap.data().fields||{};else{const published=await firebase.getDoc(firebase.doc(firebase.db,'siteContent','published'));values=published.exists()?published.data().fields||{}:{}}}ready=true;$('editor').hidden=false;render();status('Редактор готов')}catch{status('Не удалось прочитать черновик. Проверьте доступ и правила Firestore.')}}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('site-preview').contentWindow||e.data?.type!=='welcome-schema')return;schema=e.data.schema;const old=$('section').value;$('section').replaceChildren(new Option('Все разделы','all'));[...new Set(schema.map(f=>f.section))].forEach(id=>$('section').append(new Option(names[id]||id,id)));$('section').value=old||'all';load();preview()});$('site-preview').addEventListener('load',()=>$('site-preview').contentWindow.postMessage({type:'welcome-schema-request'},location.origin));
$('section').addEventListener('change',render);$('search').addEventListener('input',render);$('preview-button').addEventListener('click',()=>{$('preview-area').hidden=false;$('site-preview').hidden=false;preview();$('preview-area').scrollIntoView({behavior:'smooth'})});
async function save(publish){if(busy||!ready)return;busy=true;$('save').disabled=$('publish').disabled=true;try{if(demo){localStorage.setItem('welcome-demo-draft',JSON.stringify(values));dirty=false;status('Черновик сохранён только в этом браузере. На сайт для посетителей он не опубликован.')}else{if(!user)throw Error('auth');const payload={fields:values,updatedAt:firebase.serverTimestamp(),updatedBy:user.uid};if(publish){const batch=firebase.writeBatch(firebase.db);batch.set(firebase.doc(firebase.db,'siteContent','draft'),payload);batch.set(firebase.doc(firebase.db,'siteContent','published'),payload);await batch.commit()}else await firebase.setDoc(firebase.doc(firebase.db,'siteContent','draft'),payload);dirty=false;status(publish?'Опубликовано. Посетители увидят изменения при следующем открытии сайта.':'Черновик сохранён в Firebase. На публичном сайте изменений пока нет.')}}catch{status('Не удалось сохранить. Изменения остаются в редакторе — проверьте соединение и права доступа.')}finally{busy=false;$('save').disabled=false;$('publish').disabled=demo}}
$('save').addEventListener('click',()=>save(false));$('publish').addEventListener('click',()=>{if(confirm('Опубликовать текущие тексты для всех посетителей сайта?'))save(true)});$('export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({fields:values,schema},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='welcome-content-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
if(demo){$('mode').textContent='Локальная демонстрация: Firebase пока не подключён. Можно менять тексты, сохранять черновик в этом браузере и смотреть предпросмотр. Публикация и вход пока недоступны.';$('publish').disabled=true;load();return}
$('mode').textContent='Вход по почте и паролю. Черновики доступны только владелице сайта.';$('login').hidden=false;
(async()=>{const [a,auth,db]=await Promise.all([import('https://www.gstatic.com/firebasejs/13.0.0/firebase-app.js'),import('https://www.gstatic.com/firebasejs/13.0.0/firebase-auth.js'),import('https://www.gstatic.com/firebasejs/13.0.0/firebase-firestore.js')]);const app=a.initializeApp(config),session=auth.getAuth(app);firebase={...db,db:db.getFirestore(app)};await auth.setPersistence(session,auth.browserSessionPersistence);$('login-form').addEventListener('submit',async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{await auth.signInWithEmailAndPassword(session,$('email').value.trim(),$('password').value);$('password').value=''}catch(error){status(authError(error))}finally{btn.disabled=false}});$('reset-password').addEventListener('click',async()=>{const email=$('email');if(!email.reportValidity()||!email.value)return;const button=$('reset-password');button.disabled=true;try{await auth.sendPasswordResetEmail(session,email.value.trim());status('Если для этой почты настроен доступ, придёт письмо со ссылкой для создания или восстановления пароля. Проверьте также папку «Спам».')}catch{status('Не удалось запросить письмо. Проверьте почту и попробуйте ещё раз.')}finally{button.disabled=false}});$('logout').addEventListener('click',()=>{if(dirty&&!confirm('Выйти без сохранения изменений?'))return;auth.signOut(session)});auth.onAuthStateChanged(session,async u=>{user=u;ready=false;$('login').hidden=!!u;$('editor').hidden=true;$('logout').hidden=!u;if(u){$('mode').textContent='Вы вошли: '+u.email;await load()}else{values={};dirty=false;$('preview-area').hidden=true;$('site-preview').hidden=true;preview();status('Войдите для редактирования')}})})().catch(()=>status('Firebase недоступен. Проверьте конфигурацию и интернет-соединение.'));
})();
